(()=>{'use strict';const $=id=>document.getElementById(id),roles=['Lightweight interceptor','Armored heavyweight','Stealth specialist','Precision single-seater','Lightweight. Uncompromising. Gone.','All-terrain bruiser'];let current=4,vehicle,scene,renderer,camera,visible=true;
function select(i){current=(i+6)%6;const d=KartModels.cars[current];$('hero-car').textContent=d.n;$('hero-role').textContent=roles[current];$('car-counter').textContent=String(current+1).padStart(2,'0')+' / 06';document.querySelector('.car-meta .eyebrow').textContent='SPECIALIST / '+String(current+1).padStart(2,'0');document.querySelectorAll('.machine').forEach((e,n)=>{e.classList.toggle('active',n===current);e.setAttribute('aria-pressed',String(n===current))});if(!scene)return;if(vehicle){scene.remove(vehicle);const gs=new Set(),ms=new Set();vehicle.traverse(n=>{if(n.geometry)gs.add(n.geometry);if(n.material)ms.add(n.material)});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose())}vehicle=KartModels.create(d,d.c,false);vehicle.rotation.y=-.5;scene.add(vehicle)}
$('machine-list').innerHTML=KartModels.cars.map((d,i)=>`<button class="machine" style="--paint:#${d.c.toString(16).padStart(6,'0')}" aria-label="Preview ${d.n}" aria-pressed="false"><span class="number">${String(i+1).padStart(2,'0')} / SPECIALIST</span><i class="machine-color"></i><h3>${d.n}</h3><p>${roles[i]}</p><small>${d.ult} ↗</small></button>`).join('');document.querySelectorAll('.machine').forEach((e,i)=>e.onclick=()=>{select(i);document.querySelector('.showcase').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'})});$('prev-car').onclick=()=>select(current-1);$('next-car').onclick=()=>select(current+1);
try{const T=THREE;scene=new T.Scene();const canvas=$('showroom');renderer=new T.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputEncoding=T.sRGBEncoding;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.9;camera=new T.PerspectiveCamera(34,1,.1,80);camera.position.set(8,5.2,10);camera.lookAt(0,.5,0);scene.add(new T.HemisphereLight(0xdffaff,0x203429,.7));const light=new T.DirectionalLight(0xffffff,1.1);light.position.set(3,7,4);scene.add(light);const rim=new T.DirectionalLight(0xb6ff3b,.6);rim.position.set(-4,3,-4);scene.add(rim);const deck=new T.Mesh(new T.CylinderGeometry(4.5,4.7,.15,80),new T.MeshStandardMaterial({color:0x192c2b,metalness:.6,roughness:.38}));deck.position.y=-.12;scene.add(deck);const ring=new T.Mesh(new T.TorusGeometry(4.4,.02,6,100),new T.MeshBasicMaterial({color:0xb6ff3b,transparent:true,opacity:.65}));ring.rotation.x=Math.PI/2;ring.position.y=-.025;scene.add(ring);function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas);resize();select(4);new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(canvas);const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;let last=0;function frame(t){requestAnimationFrame(frame);if(!visible||document.hidden||t-last<32)return;last=t;if(vehicle&&!reduced)vehicle.rotation.y=-.5+Math.sin(t*.0002)*.3;renderer.render(scene,camera)}requestAnimationFrame(frame)}catch{$('showroom-fallback').hidden=false;select(4)}
fetch('track-data.json').then(r=>r.json()).then(tracks=>document.querySelectorAll('[data-track]').forEach(el=>{const pts=tracks[+el.dataset.track].pts,xx=pts.map(p=>p[0]),zz=pts.map(p=>p[2]),xmin=Math.min(...xx),zmin=Math.min(...zz),span=Math.max(Math.max(...xx)-xmin,Math.max(...zz)-zmin);const path=pts.map(p=>`${20+(p[0]-xmin)/span*260},${20+(p[2]-zmin)/span*180}`).join(' ');el.innerHTML=`<svg viewBox="0 0 300 220" aria-label="Circuit outline"><polygon points="${path}" fill="none" stroke="#ffffff08" stroke-width="18" stroke-linejoin="round"/><polygon points="${path}" fill="none" stroke="var(--track)" stroke-width="3" stroke-linejoin="round"/></svg>`})).catch(()=>{});
})();
